package org.concordia.babycdf;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import com.daml.ledger.api.v2.*;
import java.nio.file.*;import java.time.*;import java.util.*;import java.io.*;
import static org.junit.jupiter.api.Assertions.*;import static org.concordia.babycdf.SourceCatalogueCodec.*;
class SourceOpenerRealMilestoneRestartTest {
 @TempDir Path root;
 @Test void activeSameSubjectHeadRealAdapterTwoRoundsRestartAndForeignStaleMissingRefuse()throws Exception {
  root=root.toRealPath();String pkg="a".repeat(64),repo=SourceEvidenceCollector.REPO,sha="b".repeat(40);Instant now=Instant.parse("2026-11-23T00:00:00Z");var mapper=new com.fasterxml.jackson.databind.ObjectMapper();
  var comments=mapper.createArrayNode();for(int i=1;i<=3;i++){String at="2026-11-22T0"+i+":00:00Z";comments.add(mapper.createObjectNode().put("id",i).put("issue_url","https://api.github.com/repos/"+repo+"/issues/540").put("html_url","https://github.com/"+repo+"/issues/540#issuecomment-"+i).put("body",i==1?sha:"/vote").put("created_at",at).put("updated_at",at));}
  var collector=new SourceEvidenceCollector(new SourceEvidenceFetch((u,e)->{String body=u.getPath().endsWith("comments")?comments.toString():u.getPath().endsWith("events")?"[]":u.getPath().contains("commits")?"{\"sha\":\""+sha+"\",\"commit\":{\"committer\":{\"date\":\"2026-11-21T00:00:00Z\"}}}":"{\"body\":\"body\",\"updated_at\":\"2026-11-21T00:00:00Z\"}";return new SourceEvidenceFetch.Response(200,body.getBytes(),"","",Map.of());},Clock.fixed(now,ZoneOffset.UTC)));
  var capabilities=collector.collectMilestones(540,now).ready();assertEquals(2,capabilities.size());
  var observation=new SourceObservation(540,SourceObservation.Kind.MILESTONE,"https://github.com/"+repo+"/issues/540","milestone",SourceObservation.hash("body"),"open",now.minusSeconds(172800),now,184L,"parent",false,SourceObservation.hash("body"),false);var wire=observation(observation);String fingerprint=SourceCatalogueDigest.digest(wire.getRecord());
  var rows=new HashMap<String,List<EventOuterClass.CreatedEvent>>();rows.put("SourceObservationCredential",List.of(event("credential",record("opener",party(),"repo",text(repo),"observation",wire,"version",integer(1),"fingerprint",text(fingerprint),"previousDigest",SourceOpenerLedger.none()))));rows.put("AgendaGovernor",List.of(event("gov",record("opener",party()))));
  var sent=new ArrayList<CommandServiceOuterClass.SubmitAndWaitRequest>();
  var rpc=new SourceOpenerLedger.Rpc(){public Instant now(){return now;}public List<EventOuterClass.CreatedEvent> active(String m,String e){return rows.getOrDefault(e,List.of());}public void submit(CommandServiceOuterClass.SubmitAndWaitRequest request)throws IOException{
   sent.add(request);var args=request.getCommands().getCommands(0).getExercise().getChoiceArgument().getRecord();String round=IntakeLedger.text(args,"roundId");var source=IntakeLedger.field(args,"source").getOptional().getValue().getRecord();String prior=rows.getOrDefault("SourceRoundHead",List.of()).isEmpty()?"":IntakeLedger.text(rows.get("SourceRoundHead").getFirst().getCreateArguments(),"latest");var previous=IntakeLedger.field(source,"previousRound").getOptional();assertEquals(prior,previous.hasValue()?previous.getValue().getText():"");assertEquals(184,IntakeLedger.number(source,"originalProposal"));assertEquals(now.plus(Duration.ofDays(21)),timestamp(IntakeLedger.field(args,"closesAt")));
   var delivery=IntakeLedger.field(source,"pin").getVariant().getValue().getRecord();assertEquals(sha,IntakeLedger.text(delivery,"deliveryCommit"));assertEquals(observation.bodySha256(),IntakeLedger.text(delivery,"issueDigest"));long comment=IntakeLedger.number(delivery,"voteCommentId");assertEquals(Instant.parse("2026-11-22T0"+comment+":00:00Z"),timestamp(IntakeLedger.field(delivery,"voteCommentAt")));
   var snapshot=record("sourceCid",cid("credential"),"opener",party(),"observation",wire,"fingerprint",text(fingerprint),"version",integer(1),"previousDigest",SourceOpenerLedger.none(),"evidenceDigest",text(observation.bodySha256()),"pin",IntakeLedger.field(source,"pin"),"roundId",text(round),"originalProposal",integer(184),"previousRound",IntakeLedger.field(source,"previousRound"));String action="action-"+sent.size();
   var receipt=event("receipt-"+sent.size(),record("opener",party(),"proposer",party(),"roundId",text(round),"baseVersion",integer(0),"agenda",IntakeLedger.field(args,"agenda"),"actionCid",cid(action),"sourceSnapshot",some(snapshot)));
   var receipts=new ArrayList<>(rows.getOrDefault("AgendaRoundReceipt",List.of()));receipts.add(receipt);rows.put("AgendaRoundReceipt",receipts);var actions=new ArrayList<>(rows.getOrDefault("AgendaAction",List.of()));actions.add(event(action,record("opener",party(),"baseVersion",integer(0),"agenda",IntakeLedger.field(args,"agenda"),"sourceSnapshot",some(snapshot))));rows.put("AgendaAction",actions);rows.put("AgendaProposal",List.of(event("proposal",record("opener",party(),"proposer",IntakeLedger.field(args,"proposer"),"actionCid",cid(action),"subject",record("url",text(observation.url()),"body",text(fingerprint)),"sourceSnapshot",some(snapshot),"roundId",text(round),"closesAt",IntakeLedger.field(args,"closesAt")))));rows.put("SourceRoundHead",List.of(event("head",record("number",integer(540),"latest",text(round)))));
  }};
  java.util.function.Supplier<IntakeLedger> proofs=()->new IntakeLedger("opener",pkg,pkg,"gov","user",root,r->{fail();},(p,m,e)->rows.getOrDefault(e,List.of()),false);
  try(var ledger=new SourceOpenerLedger("opener",pkg,"gov","user",rpc,proofs.get());var queue=new SourceOpenerQueue(root,ledger,Duration.ofDays(21),Clock.fixed(now,ZoneOffset.UTC))){for(var c:capabilities)queue.enqueue(c,ledger.bind(c));assertEquals("opened",queue.tick());}
  rows.put("AgendaProposal",List.of());
  try(var ledger=new SourceOpenerLedger("opener",pkg,"gov","user",rpc,proofs.get());var queue=new SourceOpenerQueue(root,ledger,Duration.ofDays(21),Clock.fixed(now,ZoneOffset.UTC))){for(var c:capabilities)queue.enqueue(c,ledger.bind(c));assertEquals("opened",queue.tick());assertEquals(2,sent.size());var second=queue.snapshot().getLast().binding();assertEquals(capabilities.getFirst().roundId(),second.previousRound());
   assertThrows(IOException.class,()->ledger.validate(second));rows.put("SourceRoundHead",List.of(event("head",record("number",integer(540),"latest",text("missing")))));assertThrows(IOException.class,()->ledger.prepare(second));
   var foreign=event("foreign",record("opener",party(),"roundId",text("foreign-round"),"sourceSnapshot",some(record("opener",party(),"observation",record("number",integer(541),"kind",constructor("SourceMilestone"))))));rows.put("AgendaRoundReceipt",List.of(foreign));rows.put("SourceRoundHead",List.of(event("head",record("number",integer(540),"latest",text("foreign-round")))));assertThrows(IOException.class,()->ledger.prepare(second));assertEquals(2,sent.size());}
 }
 static ValueOuterClass.Value party(){return ValueOuterClass.Value.newBuilder().setParty("opener").build();}static ValueOuterClass.Value cid(String s){return ValueOuterClass.Value.newBuilder().setContractId(s).build();}static ValueOuterClass.Value some(ValueOuterClass.Value v){return ValueOuterClass.Value.newBuilder().setOptional(ValueOuterClass.Optional.newBuilder().setValue(v)).build();}static EventOuterClass.CreatedEvent event(String id,ValueOuterClass.Value r){return EventOuterClass.CreatedEvent.newBuilder().setContractId(id).addSignatories("opener").setCreateArguments(r.getRecord()).build();}
}
